--- 设置buff类型
---@param buffId number
function UIBattlingCharactorBuffNode:SetBuffType(buffId)
    -- if true then return end
    
    local row = CfUtils.GetCfLine(AutoIds.IdSetting573, buffId)
    if not IsNull(row) then
        local buffType = parse_number(row, "buffType")
        KTool.SetActive(self.TxtLayerBuff.gameObject, buffType == 1)
        KTool.SetActive(self.TxtLayerDebuff.gameObject, buffType == 2)
        KTool.SetActive(self.TxtLayerMidBuff.gameObject, buffType == 0)
        -- KTool.SetActive(self.TxtLayer.gameObject, buffType < 0 or buffType > 2)
        if buffType == 1 then
            self.curTxtLayer = self.TxtLayerBuff
        elseif buffType == 2 then
            self.curTxtLayer = self.TxtLayerDebuff
        elseif buffType == 0 then
            self.curTxtLayer = self.TxtLayerMidBuff
        else
            self.curTxtLayer = self.TxtLayerMidBuff
        end
        -- print("init buff  " .. tostring(buffId) .. "  buff type " .. tostring(buffType))

        if ROUND_USE_TXT then
            KTool.SetActive(self.TxtRoundBuff.gameObject, buffType == 1)
            KTool.SetActive(self.TxtRoundDebuff.gameObject, buffType == 2)
            KTool.SetActive(self.TxtRoundMidBuff.gameObject, buffType == 0)
            -- KTool.SetActive(self.TxtRound.gameObject, buffType < 0 or buffType > 2)
            if buffType == 1 then
                self.curTxtRound = self.TxtRoundBuff
            elseif buffType == 2 then
                self.curTxtRound = self.TxtRoundDebuff
            elseif buffType == 0 then
                self.curTxtRound = self.TxtRoundMidBuff
            else
                self.curTxtRound = self.TxtRoundMidBuff--self.TxtRound
            end
        end
    end
end

---SetNodeTxt
---设置节点的 txt
---@param numBuffRemain number  -- 剩余回合数
