function UIBattlingCharactorBuffNode:SetNodeTxt(numBuffRemain, numBuffLayer)
    self:SetRounds(numBuffRemain)
    self:SetLayers(numBuffLayer)
end

---SetLayersTxt
---设置 buffTxt 层数
---@param numBuffLayer number
function UIBattlingCharactorBuffNode:SetLayers(numBuffLayer, buffId)
    self.buffLayer = numBuffLayer
    if not isNull(self.curTxtLayer) then
        KTool.SetActive(self.curTxtLayer.gameObject, self.buffLayer > 1)
        self.curTxtLayer.text = tostring(checkInt(self.buffLayer))
    end
end

---SetRoundsTxt
---设置 buffTxt 回合
---@param numBuffRemain number
function UIBattlingCharactorBuffNode:SetRounds(numBuffRemain)
    if ROUND_USE_TXT then
        if not IsNull(self.curTxtRound) then
            if numBuffRemain >= 99 then
                self.booleanSignRemainImgMask = false
                KTool.SetActive(self.curTxtRound.gameObject, false)
            else
                self.curTxtRound.text = checkInt(numBuffRemain)
                self:SetRoundTxtActiveState(true)
            end
        end
    else
        if not IsNull(self.ImgRoundMask) then
            if numBuffRemain >= 99 then
                self.booleanSignRemainImgMask = false
                KTool.SetActive(self.ImgRoundMask.gameObject, false)
            else
                -- local fillAmount = numBuffRemain / self.buffRoundMax
                local fillAmount = numBuffRemain / BUFF_ROUND_MAX -- 目前的方案是约定好buff最多4回合，然后显示就按4回合满显示，不管这个buff一共几回合
                self.ImgRoundMask.fillAmount = 1 - fillAmount
                self:SetRoundTxtActiveState(true)
            end
        end
    end
end

function UIBattlingCharactorBuffNode:SetBuffNodeInShowList(boolean)
    self.booleanInShow = boolean
    self:SetShowNodeActiveState(boolean)
    self:SetLayerTxtActiveState(boolean)
    self:SetRoundTxtActiveState(boolean)
end

---SetShowNodeActiveState
---控制显示节点激活状态
---@param boolean boolean
function UIBattlingCharactorBuffNode:SetShowNodeActiveState(boolean)
    if not self.booleanInShow then
        KTool.SetActive(self.UIBattlingCharactorBuffIcon.gameObject, false)
    else
        KTool.SetActive(self.UIBattlingCharactorBuffIcon.gameObject, boolean)
    end
    -- self:SetRoundTxtActiveState(boolean)
end

---SetRoundTxtActiveState
---设置 buff 回合数 Txt 激活状态
---@param boolean boolean
function UIBattlingCharactorBuffNode:SetRoundTxtActiveState(boolean)
    if ROUND_USE_TXT then
        if not isNull(self.curTxtRound) and self.booleanSignRemainImgMask then
            if not self.booleanInShow then
                KTool.SetActive(self.curTxtRound.gameObject, false)
            else
                KTool.SetActive(self.curTxtRound.gameObject, boolean)
            end
        end
    else
        if not IsNull(self.ImgRoundMask) and self.booleanSignRemainImgMask then
            if not self.booleanInShow then
                KTool.SetActive(self.ImgRoundMask.gameObject, false)
            else
                KTool.SetActive(self.ImgRoundMask.gameObject, boolean)
            end
        end
    end
end

---SetLayerTxtActiveState
---设置层数 txt 节点显示状态
---@param boolean boolean @ 显示状态
function UIBattlingCharactorBuffNode:SetLayerTxtActiveState(boolean)
    if not isNull(self.curTxtLayer) then
        if self.booleanInShow then
            if ((not IsNull(self.buffLayer)) and self.buffLayer > 1) then
                KTool.SetActive(self.curTxtLayer.gameObject, boolean)
            end
        else
            KTool.SetActive(self.curTxtLayer.gameObject, false)
        end
    end
end

